tool_input.command:
$ports=8100..8104
foreach($p in $ports){
  try{
    $r=Invoke-WebRequest -Uri "http://localhost:$p/" -UseBasicParsing -TimeoutSec 5
    $title=([regex]'<title>(.*?)</title>').Match($r.Content).Groups[1].Value
    Write-Output "$p => HTTP $($r.StatusCode) title=[$title] len=$($r.Content.Length)"
  }catch{
    Write-Output "$p => ERROR $($_.Exception.Message)"
  }
}
Write-Output "=== nginx ==="
Get-Process nginx -ErrorAction SilentlyContinue | Select-Object Id,ProcessName,Path | Format-Table -AutoSize | Out-String

foreach($p in @(8100,8101,8102,8103,8104)){
  try{
    $r=Invoke-WebRequest -Uri "http://localhost:$p/" -UseBasicParsing -TimeoutSec 5
    $m=[regex]::Match($r.Content,'index-([A-Za-z0-9_-]{8})\.js')
    $bundle= if($m.Success){$m.Value}else{'(no index-*.js)'}
    # find title / load_title text
    $lt=[regex]::Match($r.Content,'load_title[^>]*>(.*?)</div>','Singleline').Groups[1].Value -replace '<[^>]+>','' -replace '\s+',' '
    Write-Output "$p => bundle=$bundle load_title=[$($lt.Trim())]"
  }catch{ Write-Output "$p => ERR $($_.Exception.Message)" }
}

$confRoots=@('D:\nginx\conf','D:\repository\skills\deploy-env\env-sites','D:\repository\苏州市房地产监测V3\deploy')
foreach($root in $confRoots){
  Write-Output "=== $root ==="
  if(Test-Path $root){
    Get-ChildItem -LiteralPath $root -Recurse -File -Include *.conf -ErrorAction SilentlyContinue | ForEach-Object {
      $c=Get-Content -LiteralPath $_.FullName -Raw
      if($c -match 'listen\s+81\d\d'){ Write-Output "--- $($_.FullName) ---"; ($c -split "`n" | Where-Object {$_ -match 'listen|root|server_name'}) -join "`n" }
    }
  }
}

